// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount != 10 ether);
        vm.assume(amount <= actor.balance || amount <= address(this).balance);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        // General rule: any call whose msg.value is not exactly 10 ether must revert.
        assertTrue(!ok, "call with value != 10 ether must revert");
    }
}
